insert into worlds(name,code,status,starts_at) values('جهان آریا','ARIA-01','RECRUITING',now()) on conflict(code) do nothing;
insert into worlds(name,code,status,starts_at,current_game_day) values('جهان سپهر','SEPEHR-01','RUNNING',now()-interval '3 days',3) on conflict(code) do nothing;
insert into countries(world_id,code,name,flag_emoji) select w.id,x.code,x.name,x.flag from worlds w cross join (values('IR','ایران','🇮🇷'),('TR','ترکیه','🇹🇷'),('EG','مصر','🇪🇬'),('JP','ژاپن','🇯🇵'),('DE','آلمان','🇩🇪'),('BR','برزیل','🇧🇷'),('IN','هند','🇮🇳'),('CA','کانادا','🇨🇦')) x(code,name,flag) where w.code='ARIA-01' on conflict(world_id,code) do nothing;
insert into countries(world_id,code,name,flag_emoji) select w.id,x.code,x.name,x.flag from worlds w cross join (values('IR','ایران','🇮🇷'),('FR','فرانسه','🇫🇷'),('KR','کره جنوبی','🇰🇷'),('ES','اسپانیا','🇪🇸'),('IT','ایتالیا','🇮🇹'),('IN','هند','🇮🇳'),('CA','کانادا','🇨🇦'),('AU','استرالیا','🇦🇺')) x(code,name,flag) where w.code='SEPEHR-01' on conflict(world_id,code) do nothing;
